    public void write(byte[] b, int off, int len) throws IOException {
        if (len < 0) {
            throw new IllegalArgumentException("Negative length");
        }
        if (strictWrite) {
            stream.write(b, off, len);
        } else if (sendBody) {
            hasBody = true;
            if (!endWriting) {
                if (contentLength == 0) {
                    flush();
                    endWriting = true;
                }
                boolean cont = true;
                if (contentLength != -1 && (readyLength + len > contentLength)) {
                    readyLength = contentLength;
                    len = contentLength - readyLength;
                    cont = false;
                } else if (contentLength != -1) {
                    readyLength = readyLength + (len > buffer.length - inbuffer
                            ? buffer.length - inbuffer : len);
                }
                if (inbuffer >= buffer.length) {
                    flush();
                }
                if (len < buffer.length - inbuffer) {
                    System.arraycopy(b, off, buffer, inbuffer, len);
                    inbuffer += len;
                } else {
                    int tow = buffer.length - inbuffer;
                    System.arraycopy(b, off, buffer, inbuffer, tow);
                    off += tow;
                    len -= tow;
                    inbuffer = buffer.length;
                    flush();
                    write(b, off, len);
                }
                if (!cont) {
                    flush();
                    endWriting = true;
                }
            }
        } else {
            if (len < buffer.length - inbuffer) {
                inbuffer += len;
            } else {
                int tow = buffer.length - inbuffer;
                off += tow;
                len -= tow;
                inbuffer = buffer.length;
                flush();
                write(b, off, len);
            }
        }
    }

    /**This method writes all data from the inner buffer to the outpit stream
     * and calles it's flush method.
     * @exception IOException is thrown if the output stream is closed.
     */
    public void flush() throws IOException {
        if (ignoreFlush) {
            return;
        }
        if (closed) {
            cat.debug("Cannot flush - stream closed");
            throw new IOException("Stream closed");
        }
        if (listener != null && !commited) {
            try {
                listenerFlush();
            } catch (IOException ioex) {
                commited = true;
                throw ioex;
            }
        }
        internalFlush();
        stream.flush();
    }

