    public void setBufferSize(int size) {
        if (size < buffer.length) {
            return;
        }
        if (size % 512 != 0) {
            size = (size / 512 + 1) * 512;
        }
        byte[] tbuf = new byte[size];
        System.arraycopy(buffer, 0, tbuf, 0, inbuffer);
        buffer = tbuf;
    }

