    /**This method writes data from the inner buffer to the output stream.
     * Calles the flush method of the output stream.
     * @exception IOException is thrown if any error occures while writing to the
     * output stream.
     */
    protected void internalFlush() throws IOException {
        if (inbuffer == 0) {
            return;
        }
        if (sendBody) {
            if (inbuffer > 0 && isChunked()) {
                temp = inbuffer;
                counter = 6;
                while (temp > 0) {
                    forConv[--counter] = hexNum[temp % 16];
                    temp /= 16;
                }
                stream.write(forConv, counter, 8 - counter);
                stream.write(buffer, 0, inbuffer);
                stream.write(CRLF);
            } else {
                stream.write(buffer, 0, inbuffer);
            }
        }
        if (inbuffer > 0) {
            hasSendBody = true;
        }
        transfered = transfered + inbuffer;
        inbuffer = 0;
        hasBody = false;
    }

